export type IconName = keyof typeof PATHS | string;

interface IconProps extends SVGProps<SVGSVGElement> {
  name: IconName;
  size?: number;
  /** `google` is a multi-colour brand mark and must be filled, not stroked. */
  filled?: boolean;
}

export function Icon({ name, size = 18, filled, ...rest }: IconProps) {
  const paths = PATHS[name] ?? PATHS.note!;
  const useFill = filled ?? name === 'google';
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={useFill ? 'currentColor' : 'none'}
      stroke={useFill ? 'none' : 'currentColor'}
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...rest}
    >
      {paths.map((d) => (
        <path key={d} d={d} />
      ))}
    </svg>
  );
}

/** Brand mark: a shield with a keyhole. */
/**
 * The full eQuantic lockup, for the places with room for the name — the
 * sign-in screen, not the app bar. Swapped by theme in CSS.
 */
export function Wordmark({ height = 26 }: { height?: number }) {
  return <span className="keeper-wordmark" style={{ height }} role="img" aria-label="eQuantic" />;
}

